INSERT INTO public.gk_mcqs (book_id,chapter_id,topic_id,question,correct_option,explanation,source_page,source_section,source_question_number,difficulty,confidence,canonical_hash)
SELECT b.id,c.id,t.id,'দ্বিতীয় বিশ্বযুদ্ধ শেষ হয়-','খ','Printed answer key was visually reviewed; the quality and verification boundary is documented in this batch.',721,'বিগত বছরের প্রশ্ন','14',3,'high'::confidence_level,'e985d94a2b1bcb519bedd95fe28f9713fe872f1ddfc8f63c6f84b2f5c6d87001'
FROM public.books b JOIN public.chapters c ON c.book_id=b.id AND c.slug='europe' JOIN public.topics t ON t.chapter_id=c.id AND t.slug='second-world-war-end-date-boundary-721'
WHERE b.title='Jubayer''s GK' ON CONFLICT (canonical_hash) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation,confidence=EXCLUDED.confidence;
